package dev.tripoder.runtime;

import android.content.*;
import android.os.*;
import org.json.*;

/** Owned value-contract checks alongside the actual lifecycle fixture. */
public final class RuntimeActivityPayloadProbe {
    public static JSONObject run()throws Exception{
        JSONArray checks=new JSONArray();Intent a=intent().putExtra("s","x\naction:1:a"),b=intent().putExtra("s","x").setAction("a");
        check(checks,"activity-digest-extra-action-delimiter-collision-rejected",!RuntimeActivityIntent.digest(a).equals(RuntimeActivityIntent.digest(b)));
        a=intent().addCategory("one").addCategory("two").putExtra("a",3).putExtra("b",true);b=intent().addCategory("two").addCategory("one").putExtra("b",true).putExtra("a",3);
        check(checks,"activity-digest-order-independent",RuntimeActivityIntent.digest(a).equals(RuntimeActivityIntent.digest(b)));
        check(checks,"activity-digest-category-value-bound",!RuntimeActivityIntent.digest(a).equals(RuntimeActivityIntent.digest(new Intent(b).addCategory("three"))));
        boolean malformed=false;try{RuntimeActivityIntent.digest(intent().putExtra("bad","\ud800"));}catch(java.nio.charset.CharacterCodingException expected){malformed=true;}check(checks,"activity-digest-invalid-unicode-rejected",malformed);
        check(checks,"activity-digest-distinguishes-null-from-absent",!RuntimeActivityIntent.digest(intent().putExtra("null",(String)null)).equals(RuntimeActivityIntent.digest(intent())));
        Intent empty=intent().putExtras(new Bundle());check(checks,"activity-digest-distinguishes-absent-and-empty-bundle",!RuntimeActivityIntent.digest(empty).equals(RuntimeActivityIntent.digest(intent())));
        check(checks,"activity-digest-distinguishes-number-types",!RuntimeActivityIntent.digest(intent().putExtra("n",1)).equals(RuntimeActivityIntent.digest(intent().putExtra("n",1L))));
        check(checks,"activity-digest-distinguishes-array-types",!RuntimeActivityIntent.digest(intent().putExtra("n",new int[]{1})).equals(RuntimeActivityIntent.digest(intent().putExtra("n",new long[]{1}))));
        Bundle nested=new Bundle();int[] numbers={1,2};nested.putIntArray("numbers",numbers);Intent source=intent().putExtra("nested",nested);Intent snapshot=RuntimeActivityIntent.snapshot(source);String fingerprint=RuntimeActivityIntent.digest(snapshot);numbers[0]=5;nested.putString("new","changed");source.setAction("changed");
        check(checks,"activity-snapshot-owns-nested-arrays-and-fields",fingerprint.equals(RuntimeActivityIntent.digest(snapshot))&&snapshot.getBundleExtra("nested").getIntArray("numbers")[0]==1&&!snapshot.getBundleExtra("nested").containsKey("new")&&snapshot.getAction()==null);
        Parcel parcel=Parcel.obtain();try{snapshot.writeToParcel(parcel,0);parcel.setDataPosition(0);check(checks,"activity-digest-preserved-by-real-platform-parcel",fingerprint.equals(RuntimeActivityIntent.digest(Intent.CREATOR.createFromParcel(parcel))));}finally{parcel.recycle();}
        Bundle cycle=new Bundle();cycle.putBundle("cycle",cycle);boolean recursion=false;try{RuntimeActivityIntent.digest(intent().putExtra("cycle",cycle));}catch(IllegalArgumentException expected){recursion=expected.getMessage().equals("ACTIVITY_BUNDLE_UNSUPPORTED");}check(checks,"activity-cyclic-bundle-rejected",recursion);
        boolean array=false;try{RuntimeActivityIntent.digest(intent().putExtra("large",new byte[4097]));}catch(IllegalArgumentException expected){array=expected.getMessage().equals("ACTIVITY_EXTRA_ARRAY_TOO_LARGE");}check(checks,"activity-array-limit-enforced",array);
        Bundle capabilities=new Bundle();capabilities.putBinder("binder",new Binder());boolean requestBinder=false;try{RuntimeActivityIntent.digest(intent().putExtra("nested",capabilities));}catch(IllegalArgumentException expected){requestBinder=expected.getMessage().startsWith("ACTIVITY_EXTRA_TYPE_UNSUPPORTED:");}check(checks,"activity-nested-binder-rejected",requestBinder);
        boolean identifier=false;try{RuntimeActivityIntent.digest(intent().setIdentifier("not-yet-admitted"));}catch(IllegalArgumentException expected){identifier=expected.getMessage().equals("INTENT_SHAPE_UNSUPPORTED");}check(checks,"activity-unsealed-identifier-rejected",identifier);
        boolean bounds=false;try{Intent bounded=intent();bounded.setSourceBounds(new android.graphics.Rect(1,2,3,4));RuntimeActivityIntent.digest(bounded);}catch(IllegalArgumentException expected){bounds=expected.getMessage().equals("INTENT_SHAPE_UNSUPPORTED");}check(checks,"activity-unsealed-source-bounds-rejected",bounds);
        boolean parcelable=false;try{RuntimeActivityIntent.digest(intent().putExtra("otherParcelable",new android.graphics.Rect(1,2,3,4)));}catch(IllegalArgumentException expected){parcelable=expected.getMessage().equals("ACTIVITY_EXTRA_TYPE_UNSUPPORTED:android.graphics.Rect");}check(checks,"activity-unadmitted-parcelable-rejected",parcelable);
        Intent nestedIntent=intent().setAction("nested").putExtra("numbers",new int[]{7,8});Intent intentSource=intent().putExtra("nestedIntent",nestedIntent);Intent intentSnapshot=RuntimeActivityIntent.snapshot(intentSource);String intentHash=RuntimeActivityIntent.digest(intentSnapshot);nestedIntent.setAction("changed");nestedIntent.getIntArrayExtra("numbers")[0]=99;
        Intent ownedNested=intentSnapshot.getParcelableExtra("nestedIntent",Intent.class);check(checks,"activity-snapshot-owns-nested-intent-and-arrays",intentHash.equals(RuntimeActivityIntent.digest(intentSnapshot))&&"nested".equals(ownedNested.getAction())&&ownedNested.getIntArrayExtra("numbers")[0]==7);
        check(checks,"activity-nested-intent-component-bound",!intentHash.equals(RuntimeActivityIntent.digest(intent().putExtra("nestedIntent",new Intent(ownedNested).setComponent(new ComponentName("dev.tripoder.other","dev.tripoder.other.Screen"))))));
        Intent cycleIntent=intent();cycleIntent.putExtra("self",cycleIntent);boolean intentCycle=false;try{RuntimeActivityIntent.digest(intent().putExtra("cycle",cycleIntent));}catch(IllegalArgumentException expected){intentCycle=expected.getMessage().equals("ACTIVITY_NESTED_INTENT_CYCLE_OR_DEPTH");}check(checks,"activity-nested-intent-cycle-rejected",intentCycle);
        Intent nestedClip=intent();nestedClip.setClipData(ClipData.newPlainText("data","data"));boolean nestedClipRejected=false;try{RuntimeActivityIntent.digest(intent().putExtra("nested",nestedClip));}catch(IllegalArgumentException expected){nestedClipRejected=expected.getMessage().equals("ACTIVITY_NESTED_INTENT_SHAPE_UNSUPPORTED");}check(checks,"activity-nested-intent-clip-rejected",nestedClipRejected);
        boolean nestedGrant=false;try{RuntimeActivityIntent.digest(intent().putExtra("nested",intent().setFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)));}catch(IllegalArgumentException expected){nestedGrant=expected.getMessage().equals("ACTIVITY_NESTED_INTENT_FLAGS_UNSUPPORTED");}check(checks,"activity-nested-intent-grant-flags-rejected",nestedGrant);
        java.util.ArrayList<String> list=new java.util.ArrayList<>(java.util.Arrays.asList("a",null,"b"));Intent listSource=intent().putStringArrayListExtra("list",list);Intent listSnapshot=RuntimeActivityIntent.snapshot(listSource);String listHash=RuntimeActivityIntent.digest(listSnapshot);list.set(0,"changed");check(checks,"activity-snapshot-owns-list",listHash.equals(RuntimeActivityIntent.digest(listSnapshot))&&listSnapshot.getStringArrayListExtra("list").get(0).equals("a"));
        Bundle listBundle=new Bundle();java.util.ArrayList<Object> cycleList=new java.util.ArrayList<>();cycleList.add(cycleList);listBundle.putSerializable("cycle",cycleList);boolean listCycle=false;try{RuntimeActivityIntent.digest(intent().putExtras(listBundle));}catch(IllegalArgumentException expected){listCycle=expected.getMessage().equals("ACTIVITY_LIST_CYCLE");}check(checks,"activity-list-cycle-rejected",listCycle);
        RuntimeActivityResult.require(new Intent().putExtra("integer",37).putExtra("long",Long.MIN_VALUE).putExtra("boolean",true).putExtra("string","scalar").putExtra("float",Float.NaN).putExtra("double",Double.POSITIVE_INFINITY).putExtra("short",(short)-2).putExtra("byte",(byte)9).putExtra("character",'z'));
        RuntimeActivityResult.require(null);check(checks,"activity-result-original-scalars-and-null-admitted",true);
        ParcelFileDescriptor[] pipe=ParcelFileDescriptor.createPipe();try{boolean fd=false;try{RuntimeActivityResult.require(new Intent().putExtra("fd",pipe[0]));}catch(IllegalArgumentException expected){fd=expected.getMessage().equals("RESULT_EXTRAS_UNSUPPORTED");}check(checks,"activity-result-real-fd-rejected",fd);boolean requestFd=false;try{RuntimeActivityIntent.digest(intent().putExtra("fd",pipe[0]));}catch(IllegalArgumentException expected){requestFd=expected.getMessage().equals("ACTIVITY_EXTRA_TYPE_UNSUPPORTED:android.os.ParcelFileDescriptor");}check(checks,"activity-request-real-fd-rejected",requestFd);}finally{pipe[0].close();pipe[1].close();}
        Bundle object=new Bundle();object.putBinder("binder",new Binder());boolean binder=false;try{RuntimeActivityResult.require(new Intent().putExtras(object));}catch(IllegalArgumentException expected){binder=true;}check(checks,"activity-result-binder-rejected",binder);
        Intent clip=new Intent();clip.setClipData(ClipData.newPlainText("owned","owned"));boolean denied=false;try{RuntimeActivityResult.require(clip);}catch(IllegalArgumentException expected){denied=expected.getMessage().equals("RESULT_SHAPE_UNSUPPORTED");}check(checks,"activity-result-clip-rejected",denied);
        return new JSONObject().put("passed",true).put("checks",checks);
    }
    private static Intent intent(){return new Intent().setComponent(new ComponentName("dev.tripoder.owned","dev.tripoder.owned.Screen"));}
    private static void check(JSONArray checks,String name,boolean value)throws Exception{checks.put(new JSONObject().put("name",name).put("passed",value));if(!value)throw new AssertionError(name);}
    private RuntimeActivityPayloadProbe(){}
}
